def check_constraints(R, N):
    # R is an N x N matrix where R[i][j] = 1 if reserved, 0 otherwise.

    # Calculate row and column sums
    r = [sum(R[i]) for i in range(N)]
    c = [sum(R[i][j] for i in range(N)) for j in range(N)]

    # 1. Check Constraint 1: No two reserved seats (i1, j1) and (i2, j2) can have
    # r[i1] == r[i2] AND c[j1] == c[j2] if they are distinct seats.
    reserved_seats = []
    for i in range(N):
        for j in range(N):
            if R[i][j] == 1:
                reserved_seats.append((i, j, r[i], c[j]))

    num_reserved = len(reserved_seats)

    for k in range(num_reserved):
        i1, j1, r1, c1 = reserved_seats[k]
        for l in range(k + 1, num_reserved):
            i2, j2, r2, c2 = reserved_seats[l]

            # Check if the properties match
            if r1 == r2 and c1 == c2:
                return False, f"Constraint 1 violated by S1=({i1},{j1}), S2=({i2},{j2}). R={r1}, C={c1}"

    # 2. Check Constraint 2: Two rows must have exactly m reserved seats.
    row_counts = [r[i] for i in range(N)]

    m_values = {}
    for count in row_counts:
        m_values[count] = m_values.get(count, 0) + 1

    found_m = 0
    for count, frequency in m_values.items():
        if frequency >= 2:
            # Found a count m that appears at least twice
            found_m = count
            break

    if found_m == 0:
        return False, "Constraint 2 violated: No row count appears at least twice."

    return True, found_m

